using System.Collections.Generic;public class Solution{public IList<IList<int>> VerticalOrder(TreeNode r){var o=new List<IList<int>>();if(r==null)return o;var m=new SortedDictionary<int,List<int>>();var q=new Queue<(TreeNode,int)>();q.Enqueue((r,0));while(q.Count>0){var(n,c)=q.Dequeue();if(!m.ContainsKey(c))m[c]=new();m[c].Add(n.val);if(n.left!=null)q.Enqueue((n.left,c-1));if(n.right!=null)q.Enqueue((n.right,c+1));}foreach(var v in m.Values)o.Add(v);return o;}}
